/**
 * A cena do cálculo dos "sete tempos" — porte de `componentes/viz/sete_tempos.js`.
 *
 * Cada passo da trilha troca a FASE, e a cena conta a profecia enquanto a conta
 * se forma:
 *
 * - `inicio`  → a árvore (o governo de Deus) de pé; onde a linha do tempo é cortada.
 * - `tempo`   → 3½ "tempos" medidos contra a régua dos 1.260 dias (Apocalipse 12:6):
 *               as barras só empatam quando um "tempo" vale 360 dias.
 * - `sete`    → os sete tempos empilhados; a régua dos 1.260 mostra que dá o dobro.
 * - `diaano`  → 2.520 na linha do tempo: como DIAS mal sai de 607 AEC; como ANOS
 *               atravessa até 1914.
 * - `chegada` → a soma 606 + N na régua real, com a marca na junção AEC/EC
 *               provando que o "ano zero" não existe.
 *
 * O estado vem inteiro do renderizador (`info`): a viz só consome.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  disco,
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  ptBR,
  retangulo,
  setaCheia,
  texto,
  textoDe,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const TRONCO = '#8a5a3a';
const FOLHA = '#2f8f4a';

const sete: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** A árvore do sonho: de pé, ou tombada com o toco cintado. */
  function arvore(
    ctx: CanvasRenderingContext2D,
    cx: number,
    baseY: number,
    escala: number,
    caida: boolean,
  ): void {
    const tronco = (): void => {
      retangulo(ctx, -6 * escala, -42 * escala, 12 * escala, 42 * escala, 3 * escala, TRONCO);
    };
    const copa = (clara: string, escura: string): void => {
      ctx.fillStyle = clara;
      ctx.beginPath();
      ctx.arc(0, -72 * escala, 24 * escala, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = escura;
      ctx.beginPath();
      ctx.arc(-17 * escala, -52 * escala, 16 * escala, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.arc(17 * escala, -54 * escala, 15 * escala, 0, Math.PI * 2);
      ctx.fill();
    };

    ctx.save();
    ctx.translate(cx, baseY);

    if (caida) {
      ctx.save();
      ctx.rotate(-1.08);
      tronco();
      copa('#7f8f6a', '#8b9a76');
      ctx.restore();
      retangulo(ctx, -9 * escala, -13 * escala, 18 * escala, 13 * escala, 2 * escala, '#6b4630');
    } else {
      tronco();
      copa(FOLHA, '#3ba054');
    }

    ctx.restore();
  }

  // ── Fase 1 · onde a contagem começa ───────────────────────────────────────
  function faseInicio(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const escolhido = textoDe(estado, 'escolhido');
    const certo = escolhido === '607';

    titulo(ctx, L, A, 'Onde a árvore é derrubada?');

    arvore(ctx, L * 0.16, A * 0.64, limitar(A / 250, 0.7, 1.25), certo);
    texto(
      ctx,
      certo ? 'derrubada' : 'o Reino de Deus',
      L * 0.16,
      A * 0.8,
      limitar(A * 0.05, 10, 14),
      {
        cor: certo ? cor.erro : cor.fraco,
        peso: 700,
      },
    );

    const x0 = L * 0.34;
    const x1 = L * 0.94;
    const y = A * 0.5;

    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = limitar(A * 0.016, 3, 6);
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(x0, y);
    ctx.lineTo(x1, y);
    ctx.stroke();

    const eventos = [
      { id: '537', x: x0 + (x1 - x0) * 0.12, rotulo: '537 AEC', nota: 'volta do exílio' },
      { id: '607', x: x0 + (x1 - x0) * 0.5, rotulo: 'Out. 607 AEC', nota: 'Jerusalém cai' },
      { id: '70', x: x0 + (x1 - x0) * 0.9, rotulo: '70 EC', nota: 'Roma destrói' },
    ];

    const raio = limitar(A * 0.032, 6, 12);
    for (const evento of eventos) {
      const marcado = escolhido === evento.id;
      const certoAqui = evento.id === '607';
      const corDoPonto = marcado
        ? certoAqui
          ? cor.ouro
          : cor.erro
        : certoAqui && certo
          ? cor.ouro
          : cor.azul;

      if (marcado) {
        ctx.shadowColor = corDoPonto;
        ctx.shadowBlur = raio * 1.6;
      }
      disco(ctx, evento.x, y, marcado ? raio * 1.25 : raio, corDoPonto);
      ctx.shadowBlur = 0;
      ctx.strokeStyle = cor.contraste;
      ctx.lineWidth = 2;
      ctx.stroke();

      texto(
        ctx,
        evento.rotulo,
        evento.x,
        y - raio - limitar(A * 0.05, 10, 16),
        limitar(A * 0.052, 11, 15),
        {
          cor: marcado ? corDoPonto : cor.texto,
          peso: 800,
        },
      );
      texto(
        ctx,
        evento.nota,
        evento.x,
        y + raio + limitar(A * 0.045, 9, 14),
        limitar(A * 0.04, 9, 12),
        {
          cor: cor.fraco,
        },
      );
      if (marcado && !certoAqui) {
        texto(ctx, '✗', evento.x, y, limitar(A * 0.045, 10, 14), { cor: cor.contraste, peso: 800 });
      }
    }

    const aviso =
      escolhido === ''
        ? 'Escolha o evento que interrompe o governo.'
        : certo
          ? 'A árvore cai: daqui parte a conta.'
          : 'Esse evento não derruba a árvore.';

    texto(ctx, aviso, L / 2, A * 0.92, limitar(A * 0.05, 11, 15), {
      cor: certo ? cor.verde : escolhido === '' ? cor.fraco : cor.erro,
      peso: 700,
    });
  }

  // ── Fase 2 · quanto dura UM tempo ─────────────────────────────────────────
  function faseTempo(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const dias = numeroDe(info, 'dias', 360);
    const total = numeroDe(info, 'totalDias', 3.5 * dias);
    const ok = info.ok === true;

    titulo(ctx, L, A, '3½ tempos têm de dar 1.260 dias');

    const px = L * 0.06;
    const pw = L * 0.88;
    // Os 1.260 dias ocupam 70% da largura; sobra espaço para a barra passar.
    const unidade = (pw * 0.7) / 1260;
    const yReferencia = A * 0.72;
    const yTeste = A * 0.34;
    const altura = limitar(A * 0.1, 16, 30);

    const larguraTeste = Math.min(3.5 * dias * unidade, pw);
    const corTeste = ok ? cor.verde : cor.azul;

    if (ok) {
      ctx.shadowColor = cor.verde;
      ctx.shadowBlur = 14;
    }
    retangulo(ctx, px, yTeste, larguraTeste, altura, 5, corTeste);
    ctx.shadowBlur = 0;

    // As divisões internas mostram os 3½ tempos empilhados dentro da barra.
    ctx.strokeStyle = 'rgb(255 255 255 / 75%)';
    ctx.lineWidth = 1.5;
    for (let k = 1; k < 4; k++) {
      const xx = px + Math.min(k, 3.5) * dias * unidade;
      if (xx < px + larguraTeste - 1) {
        ctx.beginPath();
        ctx.moveTo(xx, yTeste);
        ctx.lineTo(xx, yTeste + altura);
        ctx.stroke();
      }
    }

    texto(
      ctx,
      `3½ × ${ptBR(dias)} = ${ptBR(total)} dias`,
      px,
      yTeste - limitar(A * 0.05, 10, 15),
      limitar(A * 0.058, 12, 17),
      { cor: corTeste, peso: 800, alinhamento: 'left' },
    );

    retangulo(ctx, px, yReferencia, 1260 * unidade, altura, 5, cor.trilho, cor.ouro, 2);
    texto(
      ctx,
      '1.260 dias · Apocalipse 12:6',
      px,
      yReferencia + altura + limitar(A * 0.055, 11, 16),
      limitar(A * 0.05, 11, 15),
      { cor: cor.ouro, peso: 800, alinhamento: 'left' },
    );

    const xAlvo = px + 1260 * unidade;
    ctx.strokeStyle = ok ? cor.verde : cor.fraco;
    ctx.lineWidth = 2;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.moveTo(xAlvo, yTeste - 4);
    ctx.lineTo(xAlvo, yReferencia + altura + 4);
    ctx.stroke();
    ctx.setLineDash([]);

    texto(
      ctx,
      ok
        ? '360 dias por tempo — as barras batem ✔'
        : total < 1260
          ? 'A barra de cima ainda é curta.'
          : 'A barra de cima passou.',
      L / 2,
      A * 0.95,
      limitar(A * 0.05, 11, 15),
      { cor: ok ? cor.verde : cor.fraco, peso: 700 },
    );
  }

  // ── Fase 3 · sete tempos somados ──────────────────────────────────────────
  function faseSete(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const tempos = limitar(numeroDe(info, 'tempos', 0), 0, 7);
    const total = numeroDe(info, 'totalDias', tempos * 360);
    const ok = info.ok === true;

    titulo(ctx, L, A, 'Some os sete tempos');

    const px = L * 0.06;
    const pw = L * 0.88;
    const vao = pw * 0.012;
    const largura = (pw - vao * 6) / 7;
    const y = A * 0.52;
    const altura = limitar(A * 0.16, 26, 52);

    for (let i = 0; i < 7; i++) {
      const x = px + i * (largura + vao);
      const aceso = i < tempos;

      if (aceso) retangulo(ctx, x, y, largura, altura, 4, ok ? cor.verde : cor.azul);
      else retangulo(ctx, x, y, largura, altura, 4, cor.palha, cor.trilho, 1.5);

      texto(ctx, '360', x + largura / 2, y + altura / 2, limitar(largura * 0.32, 9, 15), {
        cor: aceso ? cor.contraste : cor.fraco,
        peso: 700,
      });
    }

    // A chave marca 3½ tempos: é a régua que o passo anterior estabeleceu.
    const xChave = px;
    const xChaveFim = px + 3.5 * largura + 3 * vao;
    const yChave = y - limitar(A * 0.05, 10, 16);

    ctx.strokeStyle = cor.ouro;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(xChave, yChave + 6);
    ctx.lineTo(xChave, yChave);
    ctx.lineTo(xChaveFim, yChave);
    ctx.lineTo(xChaveFim, yChave + 6);
    ctx.stroke();

    texto(
      ctx,
      '1.260 (3½ tempos)',
      (xChave + xChaveFim) / 2,
      yChave - limitar(A * 0.03, 7, 11),
      limitar(A * 0.045, 10, 13),
      { cor: cor.ouro, peso: 700 },
    );

    texto(
      ctx,
      `${tempos} × 360 = ${ptBR(total)} dias`,
      L / 2,
      y + altura + limitar(A * 0.09, 18, 30),
      limitar(A * 0.07, 14, 22),
      { cor: ok ? cor.verde : cor.texto, peso: 800 },
    );

    if (ok) {
      texto(
        ctx,
        'o dobro dos 1.260 ✔',
        L / 2,
        y + altura + limitar(A * 0.16, 30, 50),
        limitar(A * 0.05, 11, 15),
        { cor: cor.verde, peso: 700 },
      );
    }
  }

  // ── Fase 4 · dias ou anos ─────────────────────────────────────────────────
  function faseDiaAno(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const escolhido = textoDe(estado, 'escolhido');

    titulo(ctx, L, A, '2.520… dias ou anos?');

    const x0 = L * 0.08;
    const x1 = L * 0.95;
    const y = A * 0.55;

    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = limitar(A * 0.016, 3, 6);
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(x0, y);
    ctx.lineTo(x1, y);
    ctx.stroke();

    disco(ctx, x0, y, limitar(A * 0.022, 4, 8), cor.azul);
    texto(ctx, 'out. 607 AEC', x0, y + limitar(A * 0.07, 14, 22), limitar(A * 0.048, 10, 14), {
      cor: cor.texto,
      peso: 700,
      alinhamento: 'left',
    });

    // Como DIAS, os 2.520 mal saem do ponto de partida.
    const xDias = x0 + (x1 - x0) * 0.06;
    const marcouDias = escolhido === 'dias';
    setaCheia(
      ctx,
      x0,
      y - A * 0.12,
      xDias,
      y - A * 0.12,
      marcouDias ? cor.erro : cor.fraco,
      marcouDias ? 3.5 : 2,
    );
    texto(ctx, '2.520 dias → ~600 AEC', x0, y - A * 0.18, limitar(A * 0.05, 11, 15), {
      cor: marcouDias ? cor.erro : cor.fraco,
      peso: marcouDias ? 800 : 600,
      alinhamento: 'left',
    });

    // Como ANOS, atravessam a linha inteira até 1914.
    const xAnos = x0 + (x1 - x0) * 0.92;
    const marcouAnos = escolhido === 'anos';
    if (marcouAnos) {
      ctx.shadowColor = cor.verde;
      ctx.shadowBlur = 10;
    }
    setaCheia(
      ctx,
      x0,
      y + A * 0.14,
      xAnos,
      y + A * 0.14,
      marcouAnos ? cor.verde : cor.fraco,
      marcouAnos ? 4 : 2,
    );
    ctx.shadowBlur = 0;
    disco(ctx, xAnos, y + A * 0.14, limitar(A * 0.024, 5, 9), marcouAnos ? cor.verde : cor.fraco);
    texto(ctx, '2.520 anos → 1914 EC', xAnos, y + A * 0.23, limitar(A * 0.05, 11, 15), {
      cor: marcouAnos ? cor.verde : cor.fraco,
      peso: marcouAnos ? 800 : 600,
      alinhamento: 'right',
    });

    const aviso =
      escolhido === ''
        ? 'Um dia para cada ano (Números 14:34).'
        : marcouAnos
          ? 'O cumprimento maior conta ANOS ✔'
          : '7 anos não bastam — as nações seguiram.';

    texto(ctx, aviso, L / 2, A * 0.95, limitar(A * 0.05, 11, 15), {
      cor: marcouAnos ? cor.verde : escolhido === '' ? cor.fraco : cor.erro,
      peso: 700,
    });
  }

  // ── Fase 5 · onde a conta termina (a armadilha do ano zero) ───────────────
  function faseChegada(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const ano = numeroDe(info, 'ano', 1908);
    const total = numeroDe(info, 'totalAnos', 606 + ano);
    const ok = info.ok === true;
    // 1913 é a armadilha: a soma direta dá 2.520 contando um ano que não existe.
    const armadilha = ano === 1913;

    titulo(ctx, L, A, '606 + N = 2.520?');

    const px = L * 0.06;
    const pw = L * 0.88;
    const y = A * 0.44;
    const altura = limitar(A * 0.11, 18, 34);
    const unidade = pw / 2520;
    const xJuncao = px + 606 * unidade;

    retangulo(ctx, px, y, 606 * unidade, altura, 4, cor.azul);
    retangulo(
      ctx,
      xJuncao,
      y,
      ano * unidade,
      altura,
      4,
      ok ? cor.verde : armadilha ? cor.erro : cor.azulClaro,
    );

    texto(ctx, '606 anos', px + (606 * unidade) / 2, y + altura / 2, limitar(A * 0.045, 10, 14), {
      cor: cor.contraste,
      peso: 700,
    });
    texto(
      ctx,
      ptBR(ano),
      xJuncao + (ano * unidade) / 2,
      y + altura / 2,
      limitar(A * 0.045, 10, 14),
      {
        cor: cor.contraste,
        peso: 700,
      },
    );
    texto(ctx, 'out. 607 AEC', px, y - limitar(A * 0.04, 8, 13), limitar(A * 0.042, 9, 13), {
      cor: cor.fraco,
      peso: 600,
      alinhamento: 'left',
    });

    ctx.strokeStyle = cor.ouro;
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(xJuncao, y - limitar(A * 0.02, 4, 8));
    ctx.lineTo(xJuncao, y + altura + limitar(A * 0.02, 4, 8));
    ctx.stroke();

    texto(
      ctx,
      '1 AEC │ 1 EC — sem ano 0',
      xJuncao,
      y + altura + limitar(A * 0.06, 12, 20),
      limitar(A * 0.044, 9, 13),
      { cor: cor.ouro, peso: 800 },
    );

    const corDaConta = ok ? cor.verde : armadilha ? cor.erro : cor.texto;
    texto(ctx, `606 + ${ptBR(ano)} = ${ptBR(total)}`, L / 2, A * 0.76, limitar(A * 0.08, 16, 26), {
      cor: corDaConta,
      peso: 800,
    });
    texto(ctx, 'alvo: 2.520 anos', L / 2, A * 0.87, limitar(A * 0.05, 11, 15), {
      cor: cor.fraco,
      peso: 600,
    });

    const aviso = ok
      ? 'Outubro de 1914 ✔'
      : armadilha
        ? 'A soma direta (607+1.913) conta o ano 0.'
        : total < 2520
          ? 'Falta chegar a 2.520.'
          : 'Passou de 2.520.';

    texto(ctx, aviso, L / 2, A * 0.95, limitar(A * 0.048, 10, 14), { cor: corDaConta, peso: 700 });
  }

  const FASES: Readonly<
    Record<string, (ctx: CanvasRenderingContext2D, L: number, A: number) => void>
  > = {
    inicio: faseInicio,
    tempo: faseTempo,
    sete: faseSete,
    diaano: faseDiaAno,
    chegada: faseChegada,
  };

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A }) => {
      const fase = textoDe(infoDe(estado), 'fase');
      (FASES[fase] ?? faseInicio)(ctx, L, A);
    },
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default sete;
